class Book
{
    private string title;
    private int pages;
    public Book(string t, int p)
    {
        title = t;
        pages = p;
    }
    public string GetTitle()
    {
        return title;
    }
    public bool IsLong()
    {
        return pages > 300;
    }
}
public class Program
{
    static void Main()
    {
        Book b = new Book("Coding", 320);
        Console.WriteLine(b.GetTitle() + " " + b.IsLong());
    }
}

