class Account
{
    private int balance = 0;
    public void Deposit(int amount)
    {
        if (amount > 0)
            balance += amount;
    }
    public int GetBalance()
    {
        return balance;
    }
}
public class Program
{
    static void Main()
    {
        Account acc = new Account();
        acc.Deposit(100);
        acc.Deposit(-40);
        acc.Deposit(50);
        Console.WriteLine(acc.GetBalance());
    }
}

class Counter
{
    private int n = 0;
    public void Add()
    {
        n++;
    }
    public int Get()
    {
        return n;
    }
}
public class Program
{
    static void Main()
    {
        Counter a = new Counter();
        Counter b = a;
        Counter c = new Counter();
        b.Add();
        b.Add();
        c.Add();
        Console.WriteLine(a.Get() + " " + b.Get() + " " + c.Get());
    }
}
